<?php $dir = __DIR__."/app/Models"; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir)); $modelSD = []; foreach($it as $f) { if($f->getExtension() == "php") { $c = file_get_contents($f->getPathname()); if(str_contains($c, "use SoftDeletes")) { $modelSD[basename($f->getPathname(), ".php")] = true; } } } $dir = __DIR__."/database/migrations"; $migSD = 0; $files = glob("$dir/*.php"); foreach($files as $f) { $c = file_get_contents($f); if(str_contains($c, "softDeletes()")) { $migSD++; } } echo "Models with SoftDeletes: ".count($modelSD)."\nMigrations with softDeletes(): $migSD\n";
